#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
export LD_LIBRARY_PATH="/usr/lib/wsl/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
mkdir -p output reports
python3 scripts/generate.py output/profile.bin --rows 1024 --cols 4096
nsys_command="${NSYS:-nsys}"
# These three files are generated by this script; remove stale exports before capture.
rm -f output/nvfp4_trace.qdstrm output/nvfp4_trace.nsys-rep output/nvfp4_trace.sqlite
"$nsys_command" profile --trace=cuda --sample=none --cpuctxsw=none \
  --force-overwrite=true --output=output/nvfp4_trace \
  build/low_precision run --input output/profile.bin --config configs/nvfp4.toml \
  --weights output/profile.weights --output output/profile.restored --log output/profile.json \
  --warmup 5 --iterations 20 --cpu-repeats 1 > reports/nsys_capture.txt 2>&1
# Ubuntu packages may install the importer outside the target CLI's search path.
if [[ ! -f output/nvfp4_trace.nsys-rep && -f output/nvfp4_trace.qdstrm ]]; then
  importer="${NSYS_IMPORTER:-/usr/lib/nsight-systems/host-linux-x64/QdstrmImporter}"
  "$importer" -i output/nvfp4_trace.qdstrm -o output/nvfp4_trace.nsys-rep \
    > reports/nsys_import.txt 2>&1
fi
"$nsys_command" stats --force-export=true --report cuda_gpu_kern_sum,cuda_gpu_mem_time_sum,cuda_api_sum \
  --format csv output/nvfp4_trace.nsys-rep > reports/nsys_summary.csv 2> reports/nsys_stats_stderr.txt
cat reports/nsys_summary.csv
